/* From Uiverse.io by JkHuger - Tags: radio, male, female, non binary */
.__UIV_SCOPE__ .radio-container {
  margin: 0 auto;
  max-width: 300px;
  color: white;
}

.__UIV_SCOPE__ .radio-wrapper {
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .radio-button {
  display: flex;
  align-items: center;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
}

.__UIV_SCOPE__ .radio-button:hover {
  transform: translateY(-2px);
}

.__UIV_SCOPE__ .radio-button input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .radio-checkmark {
  display: inline-block;
  position: relative;
  width: 16px;
  height: 16px;
  margin-right: 10px;
  border: 2px solid #333;
  border-radius: 50%;
}

.__UIV_SCOPE__ .radio-checkmark:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #333;
  transition: all 0.2s ease-in-out;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked ~ .radio-checkmark:before {
  transform: translate(-50%, -50%) scale(1);
}

.__UIV_SCOPE__ .radio-label {
  font-size: 16px;
  font-weight: 600;
}
